<script setup>import {ref,computed} from 'vue';import {useApp} from '../stores/app';import {money} from '../services/storage';import PageTitle from '../components/PageTitle.vue';const props=defineProps({kind:String});const s=useApp(),form=ref(null),msg=ref('');const rows=computed(()=>s.data[props.kind]);function edit(p){form.value=p?{...p}:props.kind==='menu'?{name:'',variant:'Regular',category:'',image:'',price:0,active:true}:{name:'',qty:0,min:0,unit:'pcs'};msg.value=''}function save(){try{props.kind==='menu'?s.product(form.value):s.stockItem(form.value);form.value=null;msg.value='Data tersimpan'}catch(e){msg.value=e.message}}function remove(p){if(!confirm('Hapus '+p.name+'?'))return;try{props.kind==='menu'?s.removeProduct(p.id):s.removeStock(p.id);msg.value='Data dihapus'}catch(e){msg.value=e.message}}</script><template><PageTitle :title="kind==='menu'?'Manajemen menu':'Persediaan'" subtitle="Kelola data master outlet."/><button @click="edit()">Tambah data</button><p aria-live="polite">{{msg}}</p><form v-if="form" class="card narrow" @submit.prevent="save"><label>Nama<input v-model="form.name" required></label><template v-if="kind==='menu'"><label>Varian<input v-model="form.variant" required></label><label>Kategori<input v-model="form.category" required></label><label>Path atau URL foto<input v-model="form.image" placeholder="products/latte.jpg"></label><label>Harga<input type="number" min="1" v-model.number="form.price" required></label><label><input type="checkbox" v-model="form.active"> Aktif</label></template><template v-else><label>Satuan<input v-model="form.unit" required></label><label>Jumlah<input type="number" min="0" step="any" v-model.number="form.qty" required></label><label>Batas minimum<input type="number" min="0" step="any" v-model.number="form.min" required></label></template><div class="actions"><button>Simpan</button><button type="button" class="secondary" @click="form=null">Batal</button></div></form><div class="table-wrap card"><table><thead><tr><th>Nama</th><th>Detail</th><th>Nilai</th><th>Aksi</th></tr></thead><tbody><tr v-for="p in rows" :key="p.id"><td>{{p.name}}</td><td>{{kind==='menu'?p.variant+' / '+p.category:p.unit}}</td><td>{{kind==='menu'?money(p.price):p.qty+' (min '+p.min+')'}} <small v-if="kind==='stock'&&p.qty<=p.min" class="error">Stok rendah</small></td><td><button class="secondary" @click="edit(p)">Ubah</button> <button class="secondary" @click="remove(p)">Hapus</button></td></tr></tbody></table></div></template>
